band.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
# One row for each fact about the band, with a label for each item
SELECT ?facet ?value ?valueLabel WHERE {
  { wd:Q741661 rdfs:label ?value . FILTER(LANG(?value) = "en") BIND("name" AS ?facet) }
  UNION { wd:Q741661 schema:description ?value . FILTER(LANG(?value) = "en") BIND("description" AS ?facet) }
  UNION { wd:Q741661 wdt:P9989 ?value . BIND("stylized name" AS ?facet) }
  UNION { wd:Q741661 wdt:P2031 ?value . BIND("start of work period" AS ?facet) }
  UNION { wd:Q741661 wdt:P31 ?value . BIND("instance of" AS ?facet) }
  UNION { wd:Q741661 wdt:P136 ?value . BIND("genre" AS ?facet) }
  UNION { wd:Q741661 wdt:P495 ?value . BIND("country of origin" AS ?facet) }
  UNION { wd:Q741661 wdt:P138 ?value . BIND("named after" AS ?facet) }
  UNION { wd:Q741661 wdt:P264 ?value . BIND("record label" AS ?facet) }
  UNION { wd:Q741661 wdt:P170 ?value . BIND("created by" AS ?facet) }
  UNION { ?value wdt:P737 wd:Q741661 . BIND("influenced" AS ?facet) }
  OPTIONAL { ?value rdfs:label ?valueLabel . FILTER(LANG(?valueLabel) = "en") }
}

members.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
SELECT ?member ?memberLabel ?description
       (GROUP_CONCAT(DISTINCT ?roleLabel; separator=", ") AS ?roles)
       (SAMPLE(?playedByLabel) AS ?playedBy) (SAMPLE(?bornInLabel) AS ?bornIn)
       (SAMPLE(?notableLabel) AS ?notableWork) WHERE {
  { ?member wdt:P463 wd:Q741661 } UNION { wd:Q741661 wdt:P527 ?member }
  ?member rdfs:label ?memberLabel . FILTER(LANG(?memberLabel) = "en")
  OPTIONAL { ?member schema:description ?description . FILTER(LANG(?description) = "en") }
  OPTIONAL { ?member wdt:P106 ?role . ?role rdfs:label ?roleLabel . FILTER(LANG(?roleLabel) = "en") }
  OPTIONAL { ?member wdt:P175 ?player . ?player rdfs:label ?playedByLabel . FILTER(LANG(?playedByLabel) = "en") }
  OPTIONAL { ?member wdt:P19 ?place . ?place rdfs:label ?bornInLabel . FILTER(LANG(?bornInLabel) = "en") }
  OPTIONAL { ?member wdt:P800 ?notable . ?notable rdfs:label ?notableLabel . FILTER(LANG(?notableLabel) = "en") }
}
GROUP BY ?member ?memberLabel ?description

film.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?title ?year ?directorLabel ?actor ?actorLabel ?character ?characterName WHERE {
  VALUES ?film { wd:Q7810384 }
  ?film wdt:P1476 ?title .
  OPTIONAL { SELECT ?film (MIN(YEAR(?date)) AS ?year) WHERE { ?film wdt:P577 ?date } GROUP BY ?film }
  OPTIONAL { ?film wdt:P57 ?director . ?director rdfs:label ?directorLabel . FILTER(LANG(?directorLabel) = "en") }
  ?film p:P161 ?credit . ?credit ps:P161 ?actor .
  ?actor rdfs:label ?actorLabel . FILTER(LANG(?actorLabel) = "en")
  OPTIONAL { ?credit pq:P453 ?role . ?role rdfs:label ?character . FILTER(LANG(?character) = "en") }
  OPTIONAL { ?credit pq:P4633 ?characterName }
}

elsewhere.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT ?person ?personLabel ?work ?workLabel (MIN(?y) AS ?year)
       (GROUP_CONCAT(DISTINCT ?credit; separator=" and ") AS ?credits)
       (MAX(?links) AS ?sitelinks) WHERE {
  VALUES ?person { wd:Q1384181 wd:Q336074 wd:Q345325 wd:Q287607 }
  { ?work wdt:P161 ?person . BIND("cast" AS ?credit) }
  UNION { ?work wdt:P57 ?person . BIND("director" AS ?credit) }
  ?work wdt:P31 wd:Q11424 ; wikibase:sitelinks ?links .
  FILTER(?links >= 30)
  FILTER NOT EXISTS { wd:Q741661 wdt:P1441 ?work }
  OPTIONAL { ?work wdt:P577 ?date . BIND(YEAR(?date) AS ?y) }
  ?person rdfs:label ?personLabel . FILTER(LANG(?personLabel) = "en")
  ?work rdfs:label ?workLabel . FILTER(LANG(?workLabel) = "en")
}
GROUP BY ?person ?personLabel ?work ?workLabel
ORDER BY ?personLabel DESC(?sitelinks)

albums.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT ?release ?releaseLabel ?description (MIN(?y) AS ?year)
       (GROUP_CONCAT(DISTINCT ?typeLabel; separator=", ") AS ?kind)
       (MAX(?links) AS ?sitelinks) WHERE {
  ?release wdt:P175 wd:Q741661 .
  ?release rdfs:label ?releaseLabel . FILTER(LANG(?releaseLabel) = "en")
  OPTIONAL { ?release schema:description ?description . FILTER(LANG(?description) = "en") }
  OPTIONAL { ?release wdt:P31 ?type . ?type rdfs:label ?typeLabel . FILTER(LANG(?typeLabel) = "en") }
  OPTIONAL { ?release wdt:P577 ?date . BIND(YEAR(?date) AS ?y) }
  OPTIONAL { ?release wikibase:sitelinks ?links }
}
GROUP BY ?release ?releaseLabel ?description
ORDER BY ?year

saga.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?work ?workLabel ?typeLabel ?year ?directorLabel ?follows ?followsLabel WHERE {
  wd:Q741661 wdt:P1441 ?work .
  ?work rdfs:label ?workLabel . FILTER(LANG(?workLabel) = "en")
  OPTIONAL { ?work wdt:P31 ?type . ?type rdfs:label ?typeLabel . FILTER(LANG(?typeLabel) = "en") }
  OPTIONAL { ?work wdt:P577 ?date . BIND(YEAR(?date) AS ?year) }
  OPTIONAL { ?work wdt:P57 ?director . ?director rdfs:label ?directorLabel . FILTER(LANG(?directorLabel) = "en") }
  OPTIONAL { ?work wdt:P155 ?follows . ?follows rdfs:label ?followsLabel . FILTER(LANG(?followsLabel) = "en") }
}
ORDER BY ?year

drummers.query:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
SELECT ?person ?personLabel ?description ?how ?work ?workLabel ?character WHERE {
  {
    ?person wdt:P463 wd:Q741661 ; wdt:P106 wd:Q386854 .
    BIND("band member, occupation drummer" AS ?how)
  } UNION {
    wd:Q741661 wdt:P1441 ?work .
    ?work rdfs:label ?workLabel . FILTER(LANG(?workLabel) = "en")
    ?work p:P161 ?credit . ?credit ps:P161 ?person .
    ?person wdt:P106 wd:Q386854 .
    OPTIONAL { ?credit pq:P4633 ?character }
    BIND("cast member, occupation drummer" AS ?how)
  } UNION {
    wd:Q741661 wdt:P1441 ?work .
    ?work rdfs:label ?workLabel . FILTER(LANG(?workLabel) = "en")
    ?work p:P161 ?credit . ?credit ps:P161 ?person ; pq:P4633 ?character .
    FILTER(REGEX(?character, "Stumpy|Shrimpton|Childs|Besser|James Bond"))
    BIND("plays one of the band's drummers" AS ?how)
  }
  ?person rdfs:label ?personLabel . FILTER(LANG(?personLabel) = "en")
  OPTIONAL { ?person schema:description ?description . FILTER(LANG(?description) = "en") }
}
